const input = $input.first().json;
const boards = Array.isArray(input.board_tokens) && input.board_tokens.length > 0
  ? input.board_tokens
  : ['hashicorp', 'datadog', 'cloudflare', 'gitlab'];

return boards.map(token => ({
  json: {
    board_token: token,
    api_url: `https://boards-api.greenhouse.io/v1/boards/${encodeURIComponent(token)}/jobs?content=true`,
    user_preferences: input.user_preferences || {}
  }
}));

const crypto = require('crypto');
const results = [];

for (const item of $input.all()) {
  const payload = item.json;
  if (!payload || !Array.isArray(payload.jobs)) continue;
  const companyName = payload.board_token || 'Greenhouse Company';

  for (const job of payload.jobs) {
    const title = String(job.title || '').trim();
    const locationName = String(job.location?.name || 'Unspecified').trim();
    const rawHtml = String(job.content || '');
    const cleanDesc = rawHtml
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&amp;/g, '&')
      .replace(/<[^>]+>/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();

    const lowerLoc = (locationName + ' ' + cleanDesc.slice(0, 300)).toLowerCase();
    let workMode = 'unspecified';
    if (lowerLoc.includes('remote')) workMode = 'remote';
    else if (lowerLoc.includes('hybrid')) workMode = 'hybrid';
    else workMode = 'onsite';

    const appUrl = String(job.absolute_url || '').trim();
    const canonicalUrl = appUrl.split('?')[0].replace(/\/+$/, '');
    const fallbackHash = crypto
      .createHash('sha256')
      .update(`${companyName.toLowerCase()}|${title.toLowerCase()}|${locationName.toLowerCase()}`)
      .digest('hex');
    const descHash = crypto.createHash('sha256').update(cleanDesc).digest('hex');

    results.push({
      json: {
        job_id: `gh_${job.id}`,
        source: 'greenhouse',
        title,
        company: companyName.charAt(0).toUpperCase() + companyName.slice(1),
        location: locationName,
        work_mode: workMode,
        employment_type: 'full-time',
        experience_required: null,
        required_skills: [],
        preferred_skills: [],
        job_description: cleanDesc,
        description_sha256: descHash,
        salary_range: null,
        posted_at: job.updated_at || new Date().toISOString(),
        application_url: appUrl,
        canonical_url: canonicalUrl,
        fallback_dedup_hash: fallbackHash,
        status: 'discovered'
      }
    });
  }
}

return results;
